# Eval harness minimal: jalankan eval set → skor → bandingkan antar versi
import json

def jalankan_eval(prompt_template, eval_set, llm):
    skor = []
    for kasus in eval_set:                       # 50+ pasangan T-J dari kasus nyata
        jawaban = llm(prompt_template.format(**kasus))
        skor.append({
            "id": kasus["id"],
            "benar": nilai_jawaban(jawaban, kasus["jawaban_acuan"]),  # exact/rubric/judge
            "bercitasi": "[sumber:" in jawaban,
        })
    return {"akurasi": sum(s["benar"] for s in skor) / len(skor),
            "citasi": sum(s["bercitasi"] for s in skor) / len(skor)}

