# 1) CHUNKING sadar-struktur (heading-aware) — bukan potong buta per-N-karakter
def chunk_heading_aware(md_text, maks=800, overlap=100):
    bagian = split_per_heading(md_text)          # pecah di ## / ###
    chunks = []
    for b in bagian:
        for c in sliding_window(b.isi, maks, overlap):
            chunks.append({"teks": c, "sumber": b.file, "heading": b.judul})
    return chunks

