class HasilKategori(BaseModel):
    kategori: Literal["makan_minum","transportasi","belanja","tagihan","lainnya"]
    keyakinan: Literal["tinggi","sedang","rendah"]

def klasifikasi_aman(teks):
    mentah = model(teks)
    try:
        hasil = HasilKategori.model_validate_json(mentah)
    except ValidationError:
        return HasilKategori(kategori="lainnya", keyakinan="rendah")  # fallback aman
    if hasil.keyakinan == "rendah":
        antre_review_manusia(teks, hasil)          # jangan auto-commit yang ragu
    return hasil

